-- OVIRA database setup for Supabase.
-- Paste this whole file into Supabase Dashboard -> SQL Editor -> New query, then click Run.
-- Safe to run more than once: it never deletes or overwrites existing data.
-- Generated by scripts/supabase-sql.mjs; regenerate with `npm run supabase:sql` instead of editing by hand.

begin;

-- 1. Tables
CREATE TABLE IF NOT EXISTS leads (
    id TEXT PRIMARY KEY, "createdAt" TEXT NOT NULL, name TEXT NOT NULL, phone TEXT NOT NULL,
    email TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '', contact TEXT NOT NULL,
    message TEXT NOT NULL DEFAULT '', consent INTEGER NOT NULL, status TEXT NOT NULL,
    notes TEXT NOT NULL DEFAULT '', "updatedAt" TEXT NOT NULL, source TEXT NOT NULL DEFAULT '',
    "preferredDate" TEXT NOT NULL DEFAULT '', "preferredTime" TEXT NOT NULL DEFAULT ''
  );

CREATE TABLE IF NOT EXISTS appointments (
    id TEXT PRIMARY KEY, "leadId" TEXT NOT NULL UNIQUE REFERENCES leads(id) ON DELETE CASCADE,
    "createdAt" TEXT NOT NULL, name TEXT NOT NULL, phone TEXT NOT NULL, email TEXT NOT NULL DEFAULT '',
    "preferredDate" TEXT NOT NULL DEFAULT '', "preferredTime" TEXT NOT NULL DEFAULT '',
    message TEXT NOT NULL DEFAULT '', status TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '',
    "updatedAt" TEXT NOT NULL
  );

CREATE TABLE IF NOT EXISTS posts (
    id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, status TEXT NOT NULL, title TEXT NOT NULL,
    category TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', intro TEXT NOT NULL DEFAULT '',
    sections TEXT NOT NULL DEFAULT '[]', "featuredImage" TEXT NOT NULL DEFAULT '',
    author TEXT NOT NULL DEFAULT '', "publishedAt" TEXT NOT NULL DEFAULT '', "updatedAt" TEXT NOT NULL,
    "seoTitle" TEXT NOT NULL DEFAULT '', "metaDescription" TEXT NOT NULL DEFAULT ''
  );

CREATE TABLE IF NOT EXISTS myths (
    id TEXT PRIMARY KEY, myth TEXT NOT NULL, fact TEXT NOT NULL, more TEXT NOT NULL DEFAULT '',
    status TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, "createdAt" TEXT NOT NULL, "updatedAt" TEXT NOT NULL
  );

CREATE TABLE IF NOT EXISTS testimonials (
    id TEXT PRIMARY KEY, name TEXT NOT NULL, content TEXT NOT NULL, details TEXT NOT NULL DEFAULT '',
    "profileImage" TEXT NOT NULL DEFAULT '', rating INTEGER, status TEXT NOT NULL,
    position INTEGER NOT NULL DEFAULT 0, "createdAt" TEXT NOT NULL, "updatedAt" TEXT NOT NULL
  );

CREATE TABLE IF NOT EXISTS slides (
    id TEXT PRIMARY KEY, image TEXT NOT NULL, alt TEXT NOT NULL, caption TEXT NOT NULL,
    enabled INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL DEFAULT 0,
    "createdAt" TEXT NOT NULL, "updatedAt" TEXT NOT NULL
  );

CREATE TABLE IF NOT EXISTS media (
    id TEXT PRIMARY KEY, "fileName" TEXT NOT NULL, "mimeType" TEXT NOT NULL,
    size INTEGER NOT NULL, "createdAt" TEXT NOT NULL, url TEXT NOT NULL DEFAULT ''
  );

CREATE TABLE IF NOT EXISTS contact (
    id INTEGER PRIMARY KEY CHECK (id = 1), "companyName" TEXT NOT NULL, address TEXT NOT NULL,
    phone TEXT NOT NULL, whatsapp TEXT NOT NULL, email TEXT NOT NULL, "mapsUrl" TEXT NOT NULL DEFAULT ''
  );

CREATE TABLE IF NOT EXISTS socials (
    id TEXT PRIMARY KEY, platform TEXT NOT NULL, url TEXT NOT NULL,
    enabled INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL DEFAULT 0, "updatedAt" TEXT NOT NULL
  );

-- 2. Additive migrations for databases created by earlier OVIRA versions.
ALTER TABLE public.media ADD COLUMN IF NOT EXISTS "url" TEXT NOT NULL DEFAULT '';

-- 3. Lock tables away from the public Supabase API.
-- The website connects with DATABASE_URL (the postgres role), which is not affected by RLS.
-- With RLS on and no policies, the anon key cannot read leads or appointments.
alter table public.leads enable row level security;
alter table public.appointments enable row level security;
alter table public.posts enable row level security;
alter table public.myths enable row level security;
alter table public.testimonials enable row level security;
alter table public.slides enable row level security;
alter table public.media enable row level security;
alter table public.contact enable row level security;
alter table public.socials enable row level security;

-- 4. Starter content (blog articles, myths, homepage slides, contact details)
INSERT INTO posts
      (id, slug, status, title, category, description, intro, sections, "featuredImage", author, "publishedAt", "updatedAt", "seoTitle", "metaDescription")
      VALUES ('fertility-first-steps', 'fertility-first-steps', 'Published', 'A gentle guide to your first fertility conversation', 'Getting started', 'What to expect, what to bring, and how to make space for your questions.', 'Starting a fertility conversation can feel like a big step. It can also be a simple first chance to understand your options and feel heard.', '[["You can begin with questions","You do not need to arrive with a plan or a complete medical history. It can help to write down what has been on your mind, how long you have been trying, and anything you would like your care team to understand about your priorities."],["What a first visit may include","Your clinician may ask about your health and history, explain possible evaluations, and talk through next steps. The process depends on your circumstances, and you can ask for time or clarification whenever you need it."],["Make the visit yours","Consider bringing a support person, noting your questions in advance, and sharing what helps you feel comfortable. A good conversation should leave you with clearer information, not pressure to decide everything at once."]]', '', 'OVIRA', '2026-11-12T00:00:00.000Z', '2026-11-12T00:00:00.000Z', 'A gentle guide to your first fertility conversation', 'What to expect, what to bring, and how to make space for your questions.') ON CONFLICT DO NOTHING;

INSERT INTO posts
      (id, slug, status, title, category, description, intro, sections, "featuredImage", author, "publishedAt", "updatedAt", "seoTitle", "metaDescription")
      VALUES ('understanding-ovulation', 'understanding-ovulation', 'Published', 'Understanding ovulation, without the overwhelm', 'Fertility basics', 'A clear starting point for learning about the menstrual cycle and timing.', 'Ovulation is one part of the menstrual cycle, and cycles can vary. Understanding the basics can help you ask more informed questions about your own health.', '[["The cycle is not a clock","Cycle length can change from month to month. Ovulation often happens roughly two weeks before a period begins, but this timing is not the same for everyone."],["Signs and tracking","Some people notice changes in cervical fluid or use cycle tracking tools. These signs can offer clues, but they are not a diagnosis and may not predict ovulation precisely for everyone."],["When to ask for help","If you have questions about irregular cycles, pain, or trying to conceive, a clinician can help interpret your experience in context."]]', '', 'OVIRA', '2026-11-08T00:00:00.000Z', '2026-11-08T00:00:00.000Z', 'Understanding ovulation, without the overwhelm', 'A clear starting point for learning about the menstrual cycle and timing.') ON CONFLICT DO NOTHING;

INSERT INTO posts
      (id, slug, status, title, category, description, intro, sections, "featuredImage", author, "publishedAt", "updatedAt", "seoTitle", "metaDescription")
      VALUES ('fertility-and-partners', 'fertility-and-partners', 'Published', 'Fertility care includes both partners', 'Fertility basics', 'Why a whole-picture approach can make evaluation more thoughtful.', 'Fertility is shaped by many factors. Looking at the whole picture can help people understand what might be affecting their journey.', '[["A shared evaluation","Fertility factors can involve either partner, both partners, or remain unexplained. Depending on your situation, clinicians may recommend evaluation for both partners."],["Talk openly and kindly","It is common for conversations about fertility to feel personal. Making room for each person’s questions and feelings can support a more collaborative process."],["Your next step","A care team can explain which assessments may be appropriate and what each one can and cannot tell you."]]', '', 'OVIRA', '2026-11-04T00:00:00.000Z', '2026-11-04T00:00:00.000Z', 'Fertility care includes both partners', 'Why a whole-picture approach can make evaluation more thoughtful.') ON CONFLICT DO NOTHING;

INSERT INTO posts
      (id, slug, status, title, category, description, intro, sections, "featuredImage", author, "publishedAt", "updatedAt", "seoTitle", "metaDescription")
      VALUES ('ivf-explained', 'ivf-explained', 'Published', 'IVF: a clear overview of the process', 'Treatment options', 'A plain-language look at common stages and the decisions you can discuss.', 'In vitro fertilization (IVF) is one of several fertility treatment options. The details differ depending on a person’s medical needs and treatment plan.', '[["The main stages","IVF commonly involves ovarian stimulation, egg retrieval, fertilization in a laboratory, and embryo transfer. Your clinician will explain the schedule and monitoring involved for your specific plan."],["Questions worth asking","You might ask about likely timelines, medication, risks, costs, and alternatives. There is no single plan that is right for everyone."],["Support through the process","Treatment can bring a range of emotions. Ask your clinic what practical and emotional support is available at each stage."]]', '', 'OVIRA', '2026-10-30T00:00:00.000Z', '2026-10-30T00:00:00.000Z', 'IVF: a clear overview of the process', 'A plain-language look at common stages and the decisions you can discuss.') ON CONFLICT DO NOTHING;

INSERT INTO posts
      (id, slug, status, title, category, description, intro, sections, "featuredImage", author, "publishedAt", "updatedAt", "seoTitle", "metaDescription")
      VALUES ('myth-multiple-pregnancy', 'myth-multiple-pregnancy', 'Published', 'Does fertility treatment always mean twins?', 'Myths & facts', 'A closer look at treatment choices and the chance of multiple pregnancy.', 'Fertility treatment does not automatically lead to twins. The likelihood depends on the treatment and individual circumstances.', '[["Treatment can be individualized","Your clinician can discuss how different approaches may affect the chance of multiple pregnancy. In IVF, embryo transfer decisions are an important part of that conversation."],["Understanding the trade-offs","The right plan balances the chance of success with the health and safety considerations that matter to you. Ask your care team to explain the benefits and risks in plain language."],["A useful next question","You can ask: “What choices in my plan affect the chance of a multiple pregnancy, and how do we make that decision together?”"]]', '', 'OVIRA', '2026-10-26T00:00:00.000Z', '2026-10-26T00:00:00.000Z', 'Does fertility treatment always mean twins?', 'A closer look at treatment choices and the chance of multiple pregnancy.') ON CONFLICT DO NOTHING;

INSERT INTO posts
      (id, slug, status, title, category, description, intro, sections, "featuredImage", author, "publishedAt", "updatedAt", "seoTitle", "metaDescription")
      VALUES ('supporting-wellbeing', 'supporting-wellbeing', 'Published', 'Caring for your wellbeing while trying to conceive', 'Wellbeing', 'Small, compassionate ways to support yourself through an uncertain season.', 'Trying to conceive can take up emotional space. There is no right way to feel, and caring for your wellbeing is part of caring for yourself.', '[["Make room for mixed feelings","Hope, frustration, uncertainty, and fatigue can all show up. You do not have to minimize what you feel or compare your experience with someone else’s."],["Choose support that fits","Some people find it helpful to speak with a trusted person, counsellor, or support group. Others prefer private time and clear boundaries around fertility conversations."],["Ask your care team","Let your clinician know if stress is becoming hard to manage. They may be able to connect you with additional support."]]', '', 'OVIRA', '2026-10-22T00:00:00.000Z', '2026-10-22T00:00:00.000Z', 'Caring for your wellbeing while trying to conceive', 'Small, compassionate ways to support yourself through an uncertain season.') ON CONFLICT DO NOTHING;

INSERT INTO posts
      (id, slug, status, title, category, description, intro, sections, "featuredImage", author, "publishedAt", "updatedAt", "seoTitle", "metaDescription")
      VALUES ('what-is-ivf', 'what-is-ivf', 'Published', 'What Is IVF? Understanding In Vitro Fertilisation', 'Treatment options', 'A clear introduction to IVF, why it may be recommended, and what can influence outcomes.', 'Starting a family is an important goal for many people, and difficulty conceiving can make the journey challenging. In Vitro Fertilisation (IVF) is one of several fertility treatments that may help. Here is what the process involves and when it may be considered.', '[["What is IVF?","IVF, or In Vitro Fertilisation, is an assisted reproductive technology. Eggs are collected from the ovaries and combined with sperm in a specialised laboratory. As embryos develop, a suitable embryo may be transferred into the uterus, where it may implant and develop into a pregnancy. “In vitro” means “outside the body,” referring to fertilisation taking place in a laboratory."],["Why might IVF be recommended?","A fertility specialist may discuss IVF for blocked or damaged fallopian tubes, male-factor infertility such as low sperm count or poor sperm movement, ovulation disorders, endometriosis, unexplained infertility, certain age-related fertility challenges, or previous unsuccessful fertility treatments."],["Who can consider IVF?","IVF may be an option for people who have difficulty conceiving or have a medical condition affecting fertility. Eligibility and recommendations depend on age, medical history, reproductive health, and an individual fertility assessment."],["Is IVF successful?","IVF can offer an opportunity for people experiencing infertility, but success is not guaranteed. Age, egg and sperm quality, embryo development, and the underlying cause of infertility can influence outcomes. A fertility specialist can explain what may apply to your circumstances."],["Understanding your options","IVF has expanded the options available in fertility care. A conversation with a qualified fertility specialist can help you understand the treatment, alternatives, and next steps that may be appropriate for you."]]', '/assets/ivf-lab.webp', 'OVIRA', '2026-11-18T00:00:00.000Z', '2026-11-18T00:00:00.000Z', 'What Is IVF? Understanding In Vitro Fertilisation', 'A clear introduction to IVF, why it may be recommended, and what can influence outcomes.') ON CONFLICT DO NOTHING;

INSERT INTO posts
      (id, slug, status, title, category, description, intro, sections, "featuredImage", author, "publishedAt", "updatedAt", "seoTitle", "metaDescription")
      VALUES ('ivf-treatment-process', 'ivf-treatment-process', 'Published', 'IVF Treatment Process: A Step-by-Step Guide', 'Treatment options', 'Learn about the common stages of IVF, from the first assessment to a pregnancy test.', 'Understanding the IVF treatment process can make it easier to know what questions to ask. IVF involves several planned stages, and the timing and details can vary with each person’s medical needs and treatment plan.', '[["1. Initial consultation and fertility assessment","The journey begins with a consultation. Both partners may be evaluated to understand possible causes of infertility. Assessments may include hormone blood tests, ultrasound, ovarian reserve assessment, semen analysis, and evaluation of the uterus and reproductive health. The specialist uses the findings to discuss an individual treatment plan."],["2. Ovarian stimulation","Hormonal medications may be used to stimulate the ovaries to develop multiple eggs. The response is monitored with ultrasound scans and, when needed, blood tests."],["3. Trigger injection","When follicles reach an appropriate stage, a trigger injection may be given to support final egg maturation. Egg retrieval is commonly scheduled about 34–36 hours later, depending on the treatment protocol."],["4. Egg retrieval","Egg retrieval is generally performed under sedation or anaesthesia. Using ultrasound guidance, the fertility specialist collects mature eggs from the ovaries with a specialised needle."],["5. Sperm collection and fertilisation","A sperm sample is collected, or prepared donor sperm may be used. Eggs and sperm are brought together in the laboratory. In selected cases, intracytoplasmic sperm injection (ICSI) may be used, where a single sperm is injected into an egg."],["6. Embryo development","After fertilisation, embryos are monitored in specialised laboratory conditions. Embryologists assess their development and identify suitable embryos for transfer or freezing."],["7. Embryo transfer","A selected embryo is transferred into the uterus using a thin, flexible catheter. The procedure is generally straightforward and usually does not require anaesthesia."],["8. Pregnancy test","A pregnancy test is performed on the date recommended by the fertility specialist, often around 10–14 days after embryo transfer depending on the protocol. If positive, medical monitoring and an ultrasound may follow."],["A plan that is personal to you","Every IVF journey is different, and timelines may vary. Your fertility team can explain each stage, answer questions, and provide care suited to your medical needs."]]', '/assets/ivf-consultation.webp', 'OVIRA', '2026-11-17T00:00:00.000Z', '2026-11-17T00:00:00.000Z', 'IVF Treatment Process: A Step-by-Step Guide', 'Learn about the common stages of IVF, from the first assessment to a pregnancy test.') ON CONFLICT DO NOTHING;

INSERT INTO posts
      (id, slug, status, title, category, description, intro, sections, "featuredImage", author, "publishedAt", "updatedAt", "seoTitle", "metaDescription")
      VALUES ('ivf-vs-iui', 'ivf-vs-iui', 'Published', 'IVF vs IUI: Understanding the Difference', 'Treatment options', 'Compare how IUI and IVF work and why the right treatment depends on individual needs.', 'Intrauterine Insemination (IUI) and In Vitro Fertilisation (IVF) are fertility treatments that work in different ways. Understanding the basics can help you have a more informed conversation with your fertility specialist.', '[["What is IUI?","IUI is a procedure in which specially prepared sperm is placed directly inside the uterus around the time of ovulation. Fertilisation then takes place inside the body. IUI may be considered in selected cases, such as unexplained infertility, use of donor sperm, certain mild male-factor concerns, or difficulty with vaginal intercourse. It requires suitable reproductive conditions, including at least one open fallopian tube."],["What is IVF?","IVF is a treatment in which eggs are collected from the ovaries and fertilised with sperm in a laboratory. Embryos are monitored, and a suitable embryo may be transferred into the uterus. IVF may be considered for blocked or damaged fallopian tubes, certain male-factor conditions, severe endometriosis, selected ovulation disorders, unexplained infertility in appropriate circumstances, or previous unsuccessful treatment."],["Key differences","With IUI, fertilisation and embryo development happen inside the body; egg collection is not required, and prepared sperm is placed in the uterus. With IVF, eggs are collected, fertilisation and early embryo development happen in a laboratory, and an embryo is transferred into the uterus. IUI is generally simpler and monitored around ovulation, while IVF involves more treatment stages and monitoring."],["Which treatment is better?","There is no universally better treatment. The appropriate option can depend on age, duration of infertility, egg and sperm quality, fallopian tube health, previous treatment outcomes, and other medical conditions. IUI may suit some people, while IVF may be recommended directly for others."],["Is IVF more successful than IUI?","IVF may offer a higher chance of pregnancy per treatment cycle for some fertility conditions, but outcomes vary considerably. Comparing treatments without considering age, diagnosis, and other individual factors can be misleading. Ask your specialist to discuss the options and expected benefits and risks for your situation."],["Choosing a next step","IUI and IVF address different medical needs. The right treatment is the one that best fits the underlying fertility concern and your circumstances. A fertility specialist can help you understand the options."]]', '/assets/ivf-guidance.webp', 'OVIRA', '2026-11-16T00:00:00.000Z', '2026-11-16T00:00:00.000Z', 'IVF vs IUI: Understanding the Difference', 'Compare how IUI and IVF work and why the right treatment depends on individual needs.') ON CONFLICT DO NOTHING;

INSERT INTO posts
      (id, slug, status, title, category, description, intro, sections, "featuredImage", author, "publishedAt", "updatedAt", "seoTitle", "metaDescription")
      VALUES ('pcos-and-infertility', 'pcos-and-infertility', 'Published', 'PCOS and Infertility: Can You Get Pregnant with PCOS?', 'Fertility basics', 'Understand how PCOS can affect ovulation and what fertility options a clinician may discuss.', 'Polycystic Ovary Syndrome (PCOS) is a common hormonal condition during the reproductive years. A diagnosis can raise questions about fertility, but PCOS does not mean pregnancy is impossible. Many people with PCOS can achieve pregnancy with appropriate evaluation and care.', '[["What is PCOS?","PCOS is a hormonal and metabolic condition that can affect ovarian function, menstrual cycles, and ovulation. Symptoms may include irregular or missed periods, difficulty with ovulation, acne, excess facial or body hair, weight-related difficulties, and hormonal changes. Not everyone experiences the same symptoms."],["How can PCOS affect fertility?","PCOS can disrupt regular ovulation. Hormonal changes may affect egg development and release, which can make it harder to predict the fertile window and conceive. Other fertility factors may also contribute, so a complete assessment is important."],["Can people with PCOS get pregnant naturally?","Yes. Many people with PCOS conceive naturally. Irregular ovulation can make conception more challenging for some, and an early evaluation can help identify suitable next steps."],["Lifestyle management","Healthy eating, regular physical activity, and appropriate weight management can support metabolic health and may help restore regular ovulation for some people. Lifestyle support can be beneficial even when weight loss is not needed."],["Ovulation induction","A clinician may prescribe medication to stimulate ovulation. Letrozole is commonly recommended as a first-line option for ovulation induction in PCOS-related anovulatory infertility when there are no other infertility factors. Other medicines may be considered depending on individual circumstances."],["IUI and IVF","IUI may be considered in selected cases when ovulation has been achieved and other fertility factors make it appropriate. IVF may be recommended if other treatments have not worked or additional fertility factors are present. People with PCOS undergoing IVF may need careful monitoring because of an increased risk of ovarian hyperstimulation syndrome (OHSS)."],["Does PCOS mean you cannot become a parent?","No. PCOS can affect fertility, but it does not automatically mean infertility or prevent pregnancy. Many people with PCOS conceive with or without fertility treatment. Proper evaluation and individualised medical care can help guide decisions."],["Finding the right support","A PCOS diagnosis does not define your chances of becoming a parent. A qualified clinician can help you understand your health, fertility goals, and treatment options."]]', '/assets/ivf-consultation.webp', 'OVIRA', '2026-11-15T00:00:00.000Z', '2026-11-15T00:00:00.000Z', 'PCOS and Infertility: Can You Get Pregnant with PCOS?', 'Understand how PCOS can affect ovulation and what fertility options a clinician may discuss.') ON CONFLICT DO NOTHING;

INSERT INTO myths
      (id, myth, fact, more, status, position, "createdAt", "updatedAt") VALUES ('myth-1', '“Babies born through IVF are unnatural.”', 'IVF is a medical way to help fertilisation happen outside the body. After embryo transfer, pregnancy develops through the same process of growth in the uterus.', 'IVF changes how an egg and sperm meet; it does not make a baby less natural or less special. Once an embryo implants and pregnancy develops, the baby grows in the uterus. Your clinician can explain any care or monitoring recommended for your pregnancy.', 'Published', 0, '2026-11-19T13:17:58.005Z', '2026-11-19T13:17:58.005Z') ON CONFLICT DO NOTHING;

INSERT INTO myths
      (id, myth, fact, more, status, position, "createdAt", "updatedAt") VALUES ('myth-2', '“Infertility is always a woman’s problem.”', 'Fertility challenges can involve male factors, female factors, both partners, or remain unexplained.', 'Infertility is not just a woman’s issue. Male factors contribute in many couples, and female, combined, or unexplained factors may also be involved. Evaluation of both partners, when applicable, can help identify possible causes and guide next steps.', 'Published', 1, '2026-11-19T13:17:58.005Z', '2026-11-19T13:17:58.005Z') ON CONFLICT DO NOTHING;

INSERT INTO myths
      (id, myth, fact, more, status, position, "createdAt", "updatedAt") VALUES ('myth-3', '“IVF is always successful.”', 'IVF can help many people, but it cannot guarantee pregnancy or childbirth.', 'Outcomes vary with factors such as age, egg and sperm quality, embryo development, and individual health conditions. A fertility specialist can discuss how your circumstances may affect the chances of success and what treatment plan may be appropriate.', 'Published', 2, '2026-11-19T13:17:58.005Z', '2026-11-19T13:17:58.005Z') ON CONFLICT DO NOTHING;

INSERT INTO myths
      (id, myth, fact, more, status, position, "createdAt", "updatedAt") VALUES ('myth-4', '“IVF is a very painful procedure.”', 'Many people find IVF manageable, though experiences and discomfort vary from person to person.', 'Hormone injections can cause brief discomfort, bloating, or temporary side effects. Egg retrieval is usually done with sedation or anaesthesia. Your care team can explain what to expect, help manage discomfort, and advise you about symptoms during treatment.', 'Published', 3, '2026-11-19T13:17:58.005Z', '2026-11-19T13:17:58.005Z') ON CONFLICT DO NOTHING;

INSERT INTO myths
      (id, myth, fact, more, status, position, "createdAt", "updatedAt") VALUES ('myth-5', '“IVF is the last option for having a baby.”', 'IVF is one of several fertility treatments, and it is not necessarily the last step.', 'Depending on the cause and duration of infertility, age, and medical history, a clinician may recommend medication or other options, or suggest IVF earlier. A fertility assessment helps determine which approaches are suitable for your circumstances.', 'Published', 4, '2026-11-19T13:17:58.005Z', '2026-11-19T13:17:58.005Z') ON CONFLICT DO NOTHING;

INSERT INTO myths
      (id, myth, fact, more, status, position, "createdAt", "updatedAt") VALUES ('myth-6', '“IVF always results in twins or multiple pregnancies.”', 'IVF does not always result in twins; the number of embryos transferred is an important factor in multiple pregnancy.', 'Transferring one embryo can significantly reduce the chance of twins while still offering a chance of pregnancy, although identical twins can rarely occur. Your fertility specialist can recommend an embryo transfer approach based on your individual circumstances and discuss its benefits and risks.', 'Published', 5, '2026-11-19T13:17:58.005Z', '2026-11-19T13:17:58.005Z') ON CONFLICT DO NOTHING;

